1	package com.example.starter.service;
2	
3	import com.example.starter.api.ApproveRequest;
4	import com.example.starter.api.CheckinRequest;
5	import com.example.starter.api.CountRequest;
6	import com.example.starter.api.CreatePlanRequest;
7	import com.example.starter.api.DeviceConfirmRequest;
8	import com.example.starter.api.DiscrepancyResponse;
9	import com.example.starter.api.PlanResponse;
10	import com.example.starter.api.ReconciliationResponse;
11	import com.example.starter.api.SealRequest;
12	import com.example.starter.api.SettleDiscrepancyRequest;
13	import com.example.starter.domain.DiscrepancyStatus;
14	import com.example.starter.domain.PlanStatus;
15	import com.example.starter.repo.Atm;
16	import com.example.starter.repo.CheckinRow;
17	import com.example.starter.repo.Custodian;
18	import com.example.starter.repo.DiscrepancyRow;
19	import com.example.starter.repo.IdempotentRow;
20	import com.example.starter.repo.PlanRow;
21	import com.example.starter.repo.ReplenishRepository;
22	import com.fasterxml.jackson.databind.ObjectMapper;
23	import org.springframework.dao.DuplicateKeyException;
24	import org.springframework.stereotype.Service;
25	import org.springframework.transaction.annotation.Transactional;
26	
27	import java.nio.charset.StandardCharsets;
28	import java.security.MessageDigest;
29	import java.security.NoSuchAlgorithmException;
30	import java.time.Clock;
31	import java.time.Instant;
32	import java.time.LocalDate;
33	import java.time.ZoneOffset;
34	import java.time.format.DateTimeFormatter;
35	import java.util.HexFormat;
36	import java.util.List;
37	import java.util.Optional;
38	
39	/**
40	 * ATM 加钞计划与双人押运核销核心服务。
41	 *
42	 * <p>流程：预测编制 DRAFT → 审批 APPROVED（起算 4 小时押运时限）→ 两名不同押运员先后打卡后 ESCORTED
43	 * → 双人清点 COUNTED → 设备确认并三方核销 RECONCILED（不一致转 DISCREPANCY 同事务挂账）→ 日结封存 SEALED。
44	 * 押运恰满 4 小时未完成双人打卡转 ESCORT_ABNORMAL 并冻结该 ATM；
45	 * 长短款须 3 个自然日（UTC 日界）内销账，恰第 3 日受理，逾期升级并冻结责任人。
46	 * 全部写操作以 requestId 幂等：指纹覆盖 requestId 与全部业务字段。
47	 */
48	@Service
49	public class ReplenishService {
50	
51	    /** 押运时限：审批通过后 4 小时。 */
52	    static final long ESCORT_LIMIT_HOURS = 4;
53	    /** 长短款销账期限：3 个自然日（UTC 日界），恰第 3 日提交仍受理。 */
54	    static final long DISCREPANCY_DUE_DAYS = 3;
55	
56	    private final ReplenishRepository repo;
57	    private final Clock clock;
58	    private final ObjectMapper objectMapper;
59	
60	    public ReplenishService(ReplenishRepository repo, Clock clock, ObjectMapper objectMapper) {
61	        this.repo = repo;
62	        this.clock = clock;
63	        this.objectMapper = objectMapper;
64	    }
65	
66	    /** 服务动作结果：statusCode 为首次受理时的 HTTP 状态，body 为响应体。 */
67	    public record Outcome(int statusCode, Object body) {
68	        static Outcome ok(Object body) {
69	            return new Outcome(200, body);
70	        }
71	    }
72	
73	    // ==================== 预测编制 ====================
74	
75	    @Transactional
76	    public Outcome createPlan(CreatePlanRequest req) {
77	        String fingerprint = fingerprint("CREATE_PLAN", req.requestId(), req.atmCode(), String.valueOf(req.amount()));
78	        return withIdempotency(req.requestId(), "CREATE_PLAN", fingerprint, null, () -> {
79	            Atm atm = repo.findAtmByCode(req.atmCode())
80	                    .orElseThrow(() -> new BusinessException(404, "ATM 不存在: " + req.atmCode()));
81	            if (atm.frozen()) {
82	                throw new BusinessException(409, "该 ATM 已因押运异常冻结，不受理新加钞计划: " + atm.code());
83	            }
84	            Instant now = Instant.now(clock);
85	            LocalDate businessDate = LocalDate.ofInstant(now, ZoneOffset.UTC);
86	            long predicted = atm.dailyAvgWithdrawal();
87	            long planned = req.amount() == null ? predicted : req.amount();
88	            if (planned <= 0) {
89	                throw new BusinessException(409, "加钞额必须为正数");
90	            }
91	            if (planned > atm.capacity()) {
92	                throw new BusinessException(409,
93	                        "加钞额 " + planned + " 超过钞箱容量 " + atm.capacity() + "（恰等容量合法）");
94	            }
95	            long seq = repo.nextPlanNoSequence();
96	            String planNo = "P" + DateTimeFormatter.BASIC_ISO_DATE.format(businessDate)
97	                    + "-" + String.format("%05d", seq);
98	
99	            PlanRow row = new PlanRow();
100	            row.setPlanNo(planNo);
101	            row.setAtmId(atm.id());
102	            row.setBusinessDate(businessDate);
103	            row.setPredictedAmount(predicted);
104	            row.setPlannedAmount(planned);
105	            row.setStatus(PlanStatus.DRAFT);
106	            row.setCreatedAt(now);
107	            try {
108	                repo.insertPlan(row);
109	            } catch (DuplicateKeyException e) {
110	                throw new BusinessException(409, "该 ATM 当日（UTC）已存在加钞计划，唯一受理");
111	            }
112	            return Outcome.ok(toResponse(row, atm.code(), false, "计划已编制，待审批"));
113	        });
114	    }
115	
116	    // ==================== 审批 ====================
117	
118	    @Transactional
119	    public Outcome approve(long planId, ApproveRequest req) {
120	        String fingerprint = fingerprint("APPROVE", req.requestId(), String.valueOf(planId));
121	        return withIdempotency(req.requestId(), "APPROVE", fingerprint, planId, () -> {
122	            PlanRow plan = lockPlan(planId);
123	            if (plan.getSealedAt() != null) {
124	                return lateOutcome(plan, "APPROVE", "计划已封存，审批迟到仅登记");
125	            }
126	            if (plan.getStatus() != PlanStatus.DRAFT) {
127	                throw new BusinessException(409, "仅 DRAFT 状态可审批，当前状态: " + plan.getStatus());
128	            }
129	            Instant now = Instant.now(clock);
130	            plan.setApprovedAt(now);
131	            plan.setEscortDeadline(now.atZone(ZoneOffset.UTC).plusHours(ESCORT_LIMIT_HOURS).toInstant());
132	            plan.setStatus(PlanStatus.APPROVED);
133	            repo.updatePlan(plan);
134	            return Outcome.ok(toResponse(plan, atmCode(plan), false,
135	                    "审批通过，押运时限至 " + plan.getEscortDeadline()));
136	        });
137	    }
138	
139	    // ==================== 押运打卡 ====================
140	
141	    @Transactional
142	    public Outcome checkin(long planId, CheckinRequest req) {
143	        String fingerprint = fingerprint("CHECKIN", req.requestId(), String.valueOf(planId), req.custodianCode());
144	        return withIdempotency(req.requestId(), "CHECKIN", fingerprint, planId, () -> {
145	            PlanRow plan = lockPlan(planId);
146	            if (plan.getSealedAt() != null) {
147	                return lateOutcome(plan, "CHECKIN", "计划已封存，押运打卡迟到仅登记");
148	            }
149	            Custodian custodian = repo.findCustodianByCode(req.custodianCode())
150	                    .orElseThrow(() -> new BusinessException(404, "押运员不存在: " + req.custodianCode()));
151	            if (custodian.frozen()) {
152	                throw new BusinessException(409, "押运员已被冻结，不得承接押运任务: " + custodian.code());
153	            }
154	            if (plan.getStatus() == PlanStatus.ESCORT_ABNORMAL) {
155	                throw new BusinessException(409, "该单押运已异常，打卡不再受理");
156	            }
157	            if (plan.getStatus() != PlanStatus.APPROVED) {
158	                throw new BusinessException(409, "仅审批通过后可押运打卡，当前状态: " + plan.getStatus());
159	            }
160	            Instant now = Instant.now(clock);
161	            // 恰满 4 小时未完成双人打卡：自动转押运异常并冻结 ATM 后续计划（副作用随本次受理提交）
162	            if (!now.isBefore(plan.getEscortDeadline())) {
163	                markEscortAbnormal(plan);
164	                return new Outcome(409, toResponse(plan, atmCode(plan), false,
165	                        "押运时限恰满/已过，自动转押运异常并冻结该 ATM 后续计划"));
166	            }
167	            if (repo.existsCheckin(plan.getId(), custodian.id())) {
168	                throw new BusinessException(409, "同一押运员不得重复打卡: " + custodian.code());
169	            }
170	            int order = repo.countCheckins(plan.getId()) + 1; // 行锁串行化，按时间定序
171	            repo.insertCheckin(new CheckinRow(null, plan.getId(), custodian.id(), order, now, now));
172	            String message;
173	            if (order == 1) {
174	                message = "第一名押运员已打卡，单人打卡不生效，等待第二名不同押运员";
175	            } else {
176	                plan.setStatus(PlanStatus.ESCORTED);
177	                plan.setEscortCompletedAt(now);
178	                repo.updatePlan(plan);
179	                message = "第二名押运员已打卡，双人押运完成";
180	            }
181	            return Outcome.ok(toResponse(plan, atmCode(plan), false, message));
182	        });
183	    }
184	
185	    private void markEscortAbnormal(PlanRow plan) {
186	        plan.setStatus(PlanStatus.ESCORT_ABNORMAL);
187	        repo.updatePlan(plan);
188	        repo.freezeAtm(plan.getAtmId()); // 冻结后续计划
189	    }
190	
191	    // ==================== 双人清点 ====================
192	
193	    @Transactional
194	    public Outcome count(long planId, CountRequest req) {
195	        String fingerprint = fingerprint("COUNT", req.requestId(), String.valueOf(planId),
196	                String.valueOf(req.countedAmount()), req.custodianCode());
197	        return withIdempotency(req.requestId(), "COUNT", fingerprint, planId, () -> {
198	            PlanRow plan = lockPlan(planId);
199	            if (plan.getSealedAt() != null) {
200	                return lateOutcome(plan, "COUNT", "计划已封存，清点数据迟到仅登记");
201	            }
202	            Custodian custodian = repo.findCustodianByCode(req.custodianCode())
203	                    .orElseThrow(() -> new BusinessException(404, "押运员不存在: " + req.custodianCode()));
204	            if (plan.getStatus() != PlanStatus.ESCORTED) {
205	                throw new BusinessException(409, "仅双人押运完成后可清点，当前状态: " + plan.getStatus());
206	            }
207	            Instant now = Instant.now(clock);
208	            plan.setCountedAmount(req.countedAmount());
209	            plan.setCountedAt(now);
210	            plan.setCountCustodianId(custodian.id());
211	            plan.setStatus(PlanStatus.COUNTED);
212	            repo.updatePlan(plan);
213	            return Outcome.ok(toResponse(plan, atmCode(plan), false, "双人清点完成，待设备确认"));
214	        });
215	    }
216	
217	    // ==================== 设备确认与三方核销（同事务挂账） ====================
218	
219	    @Transactional
220	    public Outcome deviceConfirm(long planId, DeviceConfirmRequest req) {
221	        String fingerprint = fingerprint("DEVICE_CONFIRM", req.requestId(), String.valueOf(planId),
222	                String.valueOf(req.deviceAmount()));
223	        return withIdempotency(req.requestId(), "DEVICE_CONFIRM", fingerprint, planId, () -> {
224	            PlanRow plan = lockPlan(planId);
225	            if (plan.getSealedAt() != null) {
226	                return lateOutcome(plan, "DEVICE_CONFIRM", "计划已封存，设备确认迟到仅登记");
227	            }
228	            if (plan.getStatus() != PlanStatus.COUNTED) {
229	                throw new BusinessException(409, "仅清点完成后可设备确认，当前状态: " + plan.getStatus());
230	            }
231	            Instant now = Instant.now(clock);
232	            plan.setDeviceAmount(req.deviceAmount());
233	            plan.setDeviceConfirmedAt(now);
234	
235	            long planned = plan.getPlannedAmount();
236	            long counted = plan.getCountedAmount();
237	            long device = req.deviceAmount();
238	            String message;
239	            if (planned == counted && counted == device) {
240	                // 三方一致方可核销
241	                plan.setStatus(PlanStatus.RECONCILED);
242	                plan.setReconciledAt(now);
243	                message = "计划数、清点数、设备入账数三方一致，核销完成";
244	            } else {
245	                // 任两方不一致转长短款；挂账与核销同事务，不得核销完成而挂账未记
246	                long discrepancyAmount = counted - planned; // 挂账金额=实际-计划，正长款负短款
247	                LocalDate occurred = LocalDate.ofInstant(now, ZoneOffset.UTC);
248	                DiscrepancyRow d = new DiscrepancyRow();
249	                d.setPlanId(plan.getId());
250	                d.setAmount(discrepancyAmount);
251	                d.setStatus(DiscrepancyStatus.OPEN);
252	                d.setResponsibleCustodianId(plan.getCountCustodianId());
253	                d.setOccurredDate(occurred);
254	                d.setDueDate(occurred.plusDays(DISCREPANCY_DUE_DAYS));
255	                d.setCreatedAt(now);
256	                repo.insertDiscrepancy(d);
257	                plan.setDiscrepancyId(d.getId());
258	                plan.setStatus(PlanStatus.DISCREPANCY);
259	                message = "三方不一致转长短款，挂账金额（实际-计划）=" + discrepancyAmount
260	                        + "，须于 " + d.getDueDate() + "（UTC，含当日）前销账";
261	            }
262	            repo.updatePlan(plan);
263	            return Outcome.ok(toResponse(plan, atmCode(plan), false, message));
264	        });
265	    }
266	
267	    // ==================== 长短款销账 ====================
268	
269	    @Transactional
270	    public Outcome settleDiscrepancy(long planId, SettleDiscrepancyRequest req) {
271	        String fingerprint = fingerprint("SETTLE_DISCREPANCY", req.requestId(), String.valueOf(planId));
272	        return withIdempotency(req.requestId(), "SETTLE_DISCREPANCY", fingerprint, planId, () -> {
273	            PlanRow plan = lockPlan(planId);
274	            if (plan.getSealedAt() != null) {
275	                return lateOutcome(plan, "SETTLE_DISCREPANCY", "计划已封存，销账迟到仅登记");
276	            }
277	            DiscrepancyRow d = repo.findDiscrepancyByPlanForUpdate(planId)
278	                    .orElseThrow(() -> new BusinessException(404, "该计划无长短款挂账"));
279	            if (d.getStatus() != DiscrepancyStatus.OPEN) {
280	                throw new BusinessException(409, "挂账当前状态不可销账: " + d.getStatus());
281	            }
282	            LocalDate today = LocalDate.ofInstant(Instant.now(clock), ZoneOffset.UTC);
283	            if (today.isAfter(d.getDueDate())) {
284	                // 逾期升级并冻结责任人新任务（副作用随本次受理提交），向客户端返回 409
285	                d.setStatus(DiscrepancyStatus.ESCALATED);
286	                repo.updateDiscrepancy(d);
287	                repo.freezeCustodian(d.getResponsibleCustodianId());
288	                return new Outcome(409, toResponse(plan, atmCode(plan), false,
289	                        "销账逾期（截止 " + d.getDueDate() + " UTC），已升级并冻结责任人新任务"));
290	            }
291	            // 恰第 3 日（today==dueDate）提交仍受理
292	            Instant now = Instant.now(clock);
293	            d.setStatus(DiscrepancyStatus.SETTLED);
294	            d.setSettledAt(now);
295	            repo.updateDiscrepancy(d);
296	            plan.setStatus(PlanStatus.RECONCILED);
297	            plan.setReconciledAt(now);
298	            repo.updatePlan(plan);
299	            return Outcome.ok(toResponse(plan, atmCode(plan), false, "长短款已按期销账，核销闭环完成"));
300	        });
301	    }
302	
303	    // ==================== 日结封存（终态） ====================
304	
305	    @Transactional
306	    public Outcome seal(long planId, SealRequest req) {
307	        String fingerprint = fingerprint("SEAL", req.requestId(), String.valueOf(planId));
308	        return withIdempotency(req.requestId(), "SEAL", fingerprint, planId, () -> {
309	            PlanRow plan = lockPlan(planId);
310	            if (plan.getSealedAt() != null) {
311	                // 封存为终态：重复封存返回幂等成功
312	                return Outcome.ok(toResponse(plan, atmCode(plan), false, "计划已封存，重复封存幂等成功"));
313	            }
314	            Instant now = Instant.now(clock);
315	            plan.setSealedAt(now);
316	            plan.setStatus(PlanStatus.SEALED);
317	            repo.updatePlan(plan);
318	            return Outcome.ok(toResponse(plan, atmCode(plan), false, "已日结封存，终态"));
319	        });
320	    }
321	
322	    // ==================== 查询与复算 ====================
323	
324	    @Transactional(readOnly = true)
325	    public PlanResponse getPlan(long planId) {
326	        PlanRow plan = repo.findPlanById(planId)
327	                .orElseThrow(() -> new BusinessException(404, "计划不存在: " + planId));
328	        return toResponse(plan, atmCode(plan), false, null);
329	    }
330	
331	    @Transactional(readOnly = true)
332	    public List<PlanResponse> ledger() {
333	        return repo.findAllPlans().stream()
334	                .map(p -> toResponse(p, atmCode(p), false, null))
335	                .toList();
336	    }
337	
338	    @Transactional(readOnly = true)
339	    public ReconciliationResponse reconciliation(long planId) {
340	        PlanRow plan = repo.findPlanById(planId)
341	                .orElseThrow(() -> new BusinessException(404, "计划不存在: " + planId));
342	        boolean ready = plan.getCountedAmount() != null && plan.getDeviceAmount() != null;
343	        boolean consistent = ready
344	                && plan.getPlannedAmount() == plan.getCountedAmount().longValue()
345	                && plan.getCountedAmount().longValue() == plan.getDeviceAmount().longValue();
346	        Long discrepancyAmount = ready ? plan.getCountedAmount() - plan.getPlannedAmount() : null;
347	        return new ReconciliationResponse(
348	                plan.getId(),
349	                plan.getStatus().name(),
350	                plan.getPlannedAmount(),
351	                plan.getCountedAmount(),
352	                plan.getDeviceAmount(),
353	                consistent,
354	                discrepancyAmount,
355	                plan.getDiscrepancyId());
356	    }
357	
358	    @Transactional(readOnly = true)
359	    public DiscrepancyResponse getDiscrepancy(long planId) {
360	        DiscrepancyRow d = repo.findDiscrepancyByPlan(planId)
361	                .orElseThrow(() -> new BusinessException(404, "该计划无挂账记录"));
362	        String code = repo.findCustodianById(d.getResponsibleCustodianId())
363	                .map(Custodian::code).orElse(null);
364	        return DiscrepancyResponse.of(d, code);
365	    }
366	
367	    // ==================== 超时/逾期扫描 ====================
368	
369	    /**
370	     * 扫描并处理两类时限：APPROVED 单押运时限恰满/已过转异常冻结 ATM；
371	     * OPEN 挂账超过 dueDate 升级并冻结责任人。可由定时任务与测试可控时钟直接调用。
372	     */
373	    @Transactional
374	    public int sweepTimeouts() {
375	        return sweepTimeouts(Instant.now(clock));
376	    }
377	
378	    @Transactional
379	    public int sweepTimeouts(Instant now) {
380	        int affected = 0;
381	        for (PlanRow plan : repo.findAllPlans()) {
382	            if (plan.getStatus() == PlanStatus.APPROVED
383	                    && plan.getEscortDeadline() != null
384	                    && !now.isBefore(plan.getEscortDeadline())) {
385	                PlanRow locked = lockPlan(plan.getId());
386	                if (locked.getStatus() == PlanStatus.APPROVED) {
387	                    markEscortAbnormal(locked);
388	                    affected++;
389	                }
390	            }
391	            if (plan.getDiscrepancyId() != null) {
392	                Optional<DiscrepancyRow> opt = repo.findDiscrepancyByPlanForUpdate(plan.getId());
393	                if (opt.isPresent()) {
394	                    DiscrepancyRow d = opt.get();
395	                    LocalDate today = LocalDate.ofInstant(now, ZoneOffset.UTC);
396	                    if (d.getStatus() == DiscrepancyStatus.OPEN && today.isAfter(d.getDueDate())) {
397	                        d.setStatus(DiscrepancyStatus.ESCALATED);
398	                        repo.updateDiscrepancy(d);
399	                        repo.freezeCustodian(d.getResponsibleCustodianId());
400	                        affected++;
401	                    }
402	                }
403	            }
404	        }
405	        return affected;
406	    }
407	
408	    // ==================== 幂等支撑 ====================
409	
410	    /**
411	     * 以 requestId 为键执行动作。先插入占位留痕裁决并发，再执行业务，最后同事务回写首次响应；
412	     * 业务异常会随外层事务回滚并清除占位。同键同指纹返回首次结果，同键异指纹或处理中冲突返回 409。
413	     */
414	    private Outcome withIdempotency(String requestId, String action, String fingerprint,
415	                                    Long planId, java.util.function.Supplier<Outcome> task) {
416	        Optional<IdempotentRow> existing = repo.findIdempotent(requestId);
417	        if (existing.isPresent()) {
418	            return resolveExisting(requestId, fingerprint, existing.get());
419	        }
420	        try {
421	            repo.insertIdempotent(requestId, action, fingerprint, planId, null, null, Instant.now(clock));
422	        } catch (DuplicateKeyException e) {
423	            // 并发同键：以已存在留痕为准
424	            return resolveExisting(requestId, fingerprint,
425	                    repo.findIdempotent(requestId)
426	                            .orElseThrow(() -> new BusinessException(409, "幂等键并发冲突，请重试")));
427	        }
428	        Outcome outcome = task.get();
429	        String bodyJson;
430	        try {
431	            bodyJson = objectMapper.writeValueAsString(outcome.body());
432	        } catch (Exception e) {
433	            throw new IllegalStateException("幂等响应序列化失败", e);
434	        }
435	        repo.completeIdempotent(requestId, outcome.statusCode(), bodyJson);
436	        return outcome;
437	    }
438	
439	    private Outcome resolveExisting(String requestId, String fingerprint, IdempotentRow row) {
440	        if (!row.fingerprint().equals(fingerprint)) {
441	            throw new BusinessException(409, "requestId=" + requestId + " 已用于不同业务参数，拒绝处理");
442	        }
443	        if (row.statusCode() == null || row.responseBody() == null) {
444	            throw new BusinessException(409, "requestId=" + requestId + " 的首次请求仍在处理中，请勿并发重放");
445	        }
446	        try {
447	            return new Outcome(row.statusCode(),
448	                    objectMapper.readValue(row.responseBody(), PlanResponse.class));
449	        } catch (Exception e) {
450	            throw new IllegalStateException("幂等响应反序列化失败", e);
451	        }
452	    }
453	
454	    // ==================== 私有工具 ====================
455	
456	    private PlanRow lockPlan(long planId) {
457	        return repo.findPlanByIdForUpdate(planId)
458	                .orElseThrow(() -> new BusinessException(404, "计划不存在: " + planId));
459	    }
460	
461	    private String atmCode(PlanRow plan) {
462	        return repo.findAtmById(plan.getAtmId()).map(Atm::code).orElse(null);
463	    }
464	
465	    private Outcome lateOutcome(PlanRow plan, String eventType, String message) {
466	        Instant now = Instant.now(clock);
467	        String payload;
468	        try {
469	            payload = objectMapper.writeValueAsString(toResponse(plan, atmCode(plan), true, message));
470	        } catch (Exception e) {
471	            payload = message;
472	        }
473	        repo.insertLateEvent(plan.getId(), eventType, payload, now);
474	        return Outcome.ok(toResponse(plan, atmCode(plan), true, message));
475	    }
476	
477	    private PlanResponse toResponse(PlanRow p, String atmCode, boolean late, String message) {
478	        return PlanResponse.of(p, atmCode, p.getId() == null ? 0 : repo.countCheckins(p.getId()),
479	                late, message);
480	    }
481	
482	    private static String fingerprint(String action, String... parts) {
483	        try {
484	            MessageDigest md = MessageDigest.getInstance("SHA-256");
485	            StringBuilder sb = new StringBuilder(action);
486	            for (String part : parts) {
487	                sb.append('|').append(part);
488	            }
489	            byte[] digest = md.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
490	            return HexFormat.of().formatHex(digest);
491	        } catch (NoSuchAlgorithmException e) {
492	            throw new IllegalStateException(e);
493	        }
494	    }
495	}
