43	/**
44	 * 加钞服务 H2 事务/并发/边界测试。使用独立内存库 atm_test 与可控 UTC 时钟，
45	 * 每个用例前清理业务数据，场景间无顺序依赖。
46	 */
47	@SpringBootTest(classes = {com.example.starter.StarterApplication.class, TestClockConfig.class})
48	class ReplenishServiceFlowTest {
49	
50	    @Autowired
51	    private ReplenishService service;
52	    @Autowired
53	    private ReplenishRepository repo;
54	    @Autowired
55	    private JdbcTemplate jdbc;
56	    @Autowired
57	    private MutableClock clock;
58	
59	    @BeforeEach
60	    void clean() {
61	        clock.setInstant(TestClockConfig.BASE);
62	        jdbc.update("DELETE FROM idempotent_request");
63	        jdbc.update("DELETE FROM late_event");
64	        jdbc.update("DELETE FROM plan_discrepancy");
65	        jdbc.update("DELETE FROM escort_checkin");
66	        jdbc.update("DELETE FROM replenish_plan");
67	        jdbc.update("UPDATE atm SET frozen = 0");
68	        jdbc.update("UPDATE custodian SET frozen = 0");
69	    }
70	
71	    private static String rid() {
72	        return UUID.randomUUID().toString();
73	    }
74	
75	    private long createPlan(String atmCode, Long amount) {
76	        PlanResponse resp = (PlanResponse) service.createPlan(new CreatePlanRequest(rid(), atmCode, amount)).body();
77	        return resp.id();
78	    }
79	
80	    private long happyPlanToEscorted(String atmCode, Long amount) {
81	        long id = createPlan(atmCode, amount);
82	        service.approve(id, new ApproveRequest(rid()));
83	        service.checkin(id, new CheckinRequest(rid(), "C-01"));
84	        service.checkin(id, new CheckinRequest(rid(), "C-02"));
85	        return id;
86	    }
87	
88	    // ==================== 预测编制 / 容量边界 ====================
89	
90	    @Test
91	    void predicted_amount_uses_daily_average_and_equal_capacity_is_valid() {
92	        // 不传金额：按历史日均取现 150000 预测
93	        PlanResponse predicted = (PlanResponse) service
94	                .createPlan(new CreatePlanRequest(rid(), "ATM-0001", null)).body();
95	        assertEquals(150000L, predicted.predictedAmount());
96	        assertEquals(150000L, predicted.plannedAmount());
97	        assertEquals(PlanStatus.DRAFT.name(), predicted.status());
98	
99	        // 恰等容量合法
100	        PlanResponse equalCap = (PlanResponse) service
101	                .createPlan(new CreatePlanRequest(rid(), "ATM-0002", 600000L)).body();
102	        assertEquals(600000L, equalCap.plannedAmount());
103	    }
104	
105	    @Test
106	    void amount_over_capacity_rejected() {
107	        BusinessException ex = assertThrows(BusinessException.class,
108	                () -> service.createPlan(new CreatePlanRequest(rid(), "ATM-0002", 600001L)));
109	        assertEquals(409, ex.getStatusCode());
110	        assertEquals(0L, repo.findAllPlans().size());
111	    }
112	
113	    // ==================== 双人押运打卡 ====================
114	
115	    @Test
116	    void escort_requires_two_distinct_custodians_and_rejects_repeat() {
117	        long id = createPlan("ATM-0001", null);
118	        service.approve(id, new ApproveRequest(rid()));
119	
120	        PlanResponse first = (PlanResponse) service.checkin(id, new CheckinRequest(rid(), "C-01")).body();
121	        assertEquals(1, first.checkinCount());
122	        assertEquals(PlanStatus.APPROVED.name(), first.status(), "单人打卡不生效，押运未完成");
123	
124	        // 同一人重复打卡拒绝
125	        BusinessException repeat = assertThrows(BusinessException.class,
126	                () -> service.checkin(id, new CheckinRequest(rid(), "C-01")));
127	        assertEquals(409, repeat.getStatusCode());
128	
129	        PlanResponse second = (PlanResponse) service.checkin(id, new CheckinRequest(rid(), "C-02")).body();
130	        assertEquals(2, second.checkinCount());
131	        assertEquals(PlanStatus.ESCORTED.name(), second.status());
132	        assertNotNull(second.escortCompletedAt());
133	    }
134	
135	    // ==================== 恰 4 小时押运异常（受理时即时判定 + 扫描） ====================
136	
137	    @Test
138	    void exactly_four_hours_without_second_checkin_marks_abnormal_and_freezes_atm() {
139	        long id = createPlan("ATM-0001", null);
140	        service.approve(id, new ApproveRequest(rid()));
141	        // 审批于 08:00，截止 12:00；11:59:59 第一名打卡仍有效
142	        clock.setInstant(Instant.parse("2026-09-20T11:59:59Z"));
143	        service.checkin(id, new CheckinRequest(rid(), "C-01"));
144	
145	        // 恰满 4 小时：第二名打卡不再受理，自动转异常并冻结，响应 409
146	        clock.setInstant(Instant.parse("2026-09-20T12:00:00Z"));
147	        var lateCheckin = service.checkin(id, new CheckinRequest(rid(), "C-02"));
148	        assertEquals(409, lateCheckin.statusCode());
149	
150	        PlanRow plan = repo.findPlanById(id).orElseThrow();
151	        assertEquals(PlanStatus.ESCORT_ABNORMAL, plan.getStatus());
152	        Atm atm = repo.findAtmByCode("ATM-0001").orElseThrow();
153	        assertTrue(atm.frozen(), "押运异常应冻结该 ATM 后续计划");
154	
155	        // 冻结后该 ATM 不受理新计划
156	        BusinessException blocked = assertThrows(BusinessException.class,
157	                () -> service.createPlan(new CreatePlanRequest(rid(), "ATM-0001", null)));
