package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 节假日临时加钞计划生成请求。按合成节假日日历对节前 3 日窗口内全部网点
 * 做峰值预测，超出钞箱日均阈值 150% 的网点自动生成临时计划。
 * requestId 幂等：同键同参返回首次结果，同键异参 409。
 */
public record GenerateTemporaryRequest(
        @NotBlank String requestId
) {
}

package com.example.starter.api;

import java.time.LocalDate;
import java.util.List;

/**
 * 临时加钞计划生成结果。preHolidayWindow=false 表示当日不在任何节假日前 3 日窗口内，
 * 未做任何预测与生成；plans 为本次生成的临时计划（含被裁决让路的 YIELDED 单）。
 */
public record TemporaryGenerateResponse(
        LocalDate businessDate,
        boolean preHolidayWindow,
        int generatedCount,
        List<PlanResponse> plans,
        String message
) {
}

package com.example.starter.api;

import com.example.starter.repo.FastTrackDecisionRow;

import java.time.Instant;
import java.time.LocalDate;

