/**
 * 查询同一 ATM 当前执行中加钞单（已批准且押运/清点未闭环：APPROVED/ESCORTED/COUNTED）。
 * 不变式：同一 ATM 同时刻至多一张执行中单。
 */
public Optional<PlanRow> findExecutingPlan(long atmId) {
    List<PlanRow> rows = jdbc.query(
            "SELECT * FROM replenish_plan WHERE atm_id = ? AND status IN ('APPROVED','ESCORTED','COUNTED') "
                    + "ORDER BY id",
            PLAN_MAPPER, atmId);
    return rows.isEmpty() ? Optional.empty() : Optional.of(rows.get(0));
}

